def count_zeros(n):
    """Counts the number of times the digit 0 appears in the decimal expansion of n."""
    s = str(n)
    return s.count('0')

L = 1000
R_L = int('1' * L)
A_target = 333

results = {}

# Test d = 2 through 9
for d in range(2, 10):
    M = d * R_L
    Q = M // 3
    A = count_zeros(Q)
    results[d] = A

print("--- Results for M consisting of d identical digits, N=3 ---")
for d, A in results.items():
    print(f"d={d}, Number of zeros A = {A}")

# Check if any result exceeds the hypothesis threshold
exceeded = False
for d, A in results.items():
    if A > A_target:
        exceeded = True
        print(f"Result d={d} exceeds 333.")
        break

if not exceeded:
    print("No case resulted in A > 333.")
